"""Targeted geometry update for the editable upholstered bed generator.

The original generator is gzip-packed to keep the repository compact. This patch
is deliberately isolated in plain Python so the bed design remains reviewable.
"""
from __future__ import annotations

OLD_GEOMETRY = "# ----------------------- PILLOWS AND HEADBOARD -----------------------\n# Two substantial sleep pillows plus smaller slate accent cushions, each independently modeled.\nfor side in (-1,1):\n    x=side*.49\n    superellipsoid(f'Sleep_pillow_{side}',(x,1.095,-1.115),(.52,.175,.335),'sheet',.48,72,44,taper=.34)\n    # Fine seam along the pillow's visible front crown.\n    curve_tube(f'Sleep_pillow_piping_{side}',[(x+u,1.19,-1.405+.025*math.cos(u*2.2)) for u in np.linspace(-.43,.43,28)],.0024,'pillow')\nfor side in (-1,1):\n    x=side*.285\n    superellipsoid(f'Slate_accent_cushion_{side}',(x,1.215,-.795),(.37,.155,.245),'pillow',.50,64,40,taper=.26)\n# A compact lumbar cushion in muted steel blue to layer the pillows.\nsuperellipsoid('Lumbar_cushion',(0,1.245,-.57),(.46,.135,.155),'throw',.53,64,36,taper=.30)\n\n# Structural headboard shell and seven individual, vertically channeled upholstered pads.\n# The channels have eased shoulders, a softly bowed face, and visible shadow seams.\nsuperellipsoid('Headboard_back_shell',(0,1.185,-1.575),(1.29,.925,.115),'charcoal2',.50,88,52)\nsuperellipsoid('Headboard_top_rail',(0,2.035,-1.475),(1.245,.085,.125),'charcoal',.55,72,36)\nfor i in range(7):\n    x=(i-3)*.354\n    superellipsoid(f'Headboard_channel_{i+1:02d}',(x,1.275,-1.435),(.174,.735,.112),'charcoal',.50,64,44,taper=.18)\n    # Delicate stitched inset down the centre of every padded section.\n    curve_tube(f'Headboard_channel_stitch_{i+1:02d}',[(x,0.72+j*.043,-1.326+.006*math.cos(j*.18)) for j in range(29)],.00115,'charcoal2')\n# Side wings roll forward just a little, framing the upholstered centre panel.\nfor side in (-1,1):\n    superellipsoid(f'Headboard_side_bolster_{side}',(side*1.205,1.255,-1.415),(.105,.77,.135),'charcoal2',.50,56,36)\n# Rear support brackets are hidden in normal view but add a credible connection to the frame.\nfor side in (-1,1):\n    boxsoft(f'Headboard_mount_{side}',(side*.92,.74,-1.53),(.105,.48,.13),'underside',.40)\n"

NEW_GEOMETRY = "# ----------------------- PILLOWS AND HEADBOARD -----------------------\n# Two substantial sleep pillows plus smaller slate accent cushions, each independently modeled.\nfor side in (-1,1):\n    x=side*.49\n    superellipsoid(f'Sleep_pillow_{side}',(x,1.095,-1.115),(.52,.175,.335),'sheet',.48,72,44,taper=.34)\n    # Fine seam along the pillow's visible front crown.\n    curve_tube(f'Sleep_pillow_piping_{side}',[(x+u,1.19,-1.405+.025*math.cos(u*2.2)) for u in np.linspace(-.43,.43,28)],.0024,'pillow')\nfor side in (-1,1):\n    x=side*.285\n    superellipsoid(f'Slate_accent_cushion_{side}',(x,1.215,-.795),(.37,.155,.245),'pillow',.50,64,40,taper=.26)\n# A compact lumbar cushion in muted steel blue to layer the pillows.\nsuperellipsoid('Lumbar_cushion',(0,1.245,-.57),(.46,.135,.155),'throw',.53,64,36,taper=.30)\n\n# Reference-matched black upholstered diamond-tufted headboard.\n# A padded backing, four perimeter rails and individually crowned diamond cells\n# recreate the PU-leather look of the supplied 4 EVER WINNER reference.\nmaterials['headboard_crystal'] = PBRMaterial(\n    name='Polished crystal-look tuft buttons',\n    baseColorFactor=[215,226,246,255],\n    metallicFactor=0.60,\n    roughnessFactor=0.12,\n    doubleSided=True\n)\nsuperellipsoid(\n    'Headboard_outer_shell',(0,1.185,-1.575),\n    (1.29,.925,.115),'charcoal2',.50,96,56\n)\nboxsoft(\n    'Headboard_quilt_backing',(0,1.175,-1.425),\n    (2.42,1.56,.15),'charcoal2',.40\n)\n\n# Softly eased padded black perimeter, rather than an exposed silver rectangle.\nsuperellipsoid('Headboard_top_rail',(0,1.985,-1.405),(1.29,.095,.13),'charcoal2',.50,80,44)\nsuperellipsoid('Headboard_bottom_rail',(0,.375,-1.405),(1.29,.075,.13),'charcoal2',.50,80,44)\nfor side in (-1,1):\n    superellipsoid(\n        f'Headboard_side_frame_{side}',\n        (side*1.235,1.18,-1.405),(.075,.785,.13),\n        'charcoal2',.50,64,40\n    )\n\ndef headboard_diamond_pad(name,cx,cy,rx,ry,z_base,bulge):\n    # Radial subdivision keeps the diamond perimeter crisp while giving the\n    # upholstery a continuous, rounded crown with a tangent-soft edge.\n    radial_steps=20\n    angular_steps=64\n    verts=[(cx,cy,z_base+bulge)]\n    uvs=[(.5,.5)]\n    for ring in range(1,radial_steps+1):\n        radius=ring/radial_steps\n        crown=math.cos(.5*math.pi*radius)**2\n        for i in range(angular_steps):\n            theta=2*math.pi*i/angular_steps\n            cs=math.cos(theta); sn=math.sin(theta)\n            perimeter=1.0/(abs(cs)+abs(sn))\n            px=radius*cs*perimeter\n            py=radius*sn*perimeter\n            verts.append((cx+rx*px,cy+ry*py,z_base+bulge*crown))\n            uvs.append((.5+.5*px,.5+.5*py))\n    faces=[]\n    first=1\n    for i in range(angular_steps):\n        a=first+i\n        b=first+(i+1)%angular_steps\n        faces.append((0,a,b))\n    for ring in range(radial_steps-1):\n        inner=1+ring*angular_steps\n        outer=inner+angular_steps\n        for i in range(angular_steps):\n            nxt=(i+1)%angular_steps\n            a=inner+i\n            b=outer+i\n            c=outer+nxt\n            d=inner+nxt\n            faces.extend([(a,b,c),(a,c,d)])\n    return add_mesh(name,verts,faces,uvs,'charcoal')\n\n# Five columns by four rows of evenly spaced, softly crowned diamond cushions.\n# The field is lifted within the existing headboard frame so more tufting and\n# two button rows remain visible above the original pillows.\ndiamond_x=[-.92,-.46,0.0,.46,.92]\ndiamond_y=[.83,1.14,1.45,1.76]\ndiamond_rx=.225;diamond_ry=.155;diamond_base_z=-1.354\ndiamond_index=0\nfor cy in diamond_y:\n    for cx in diamond_x:\n        diamond_index+=1\n        headboard_diamond_pad(\n            f'Headboard_diamond_tuft_{diamond_index:02d}',\n            cx,cy,diamond_rx,diamond_ry,diamond_base_z,.11\n        )\n        corners=[\n            (cx,cy+diamond_ry,diamond_base_z-.003),\n            (cx+diamond_rx,cy,diamond_base_z-.003),\n            (cx,cy-diamond_ry,diamond_base_z-.003),\n            (cx-diamond_rx,cy,diamond_base_z-.003),\n            (cx,cy+diamond_ry,diamond_base_z-.003)\n        ]\n        curve_tube(\n            f'Headboard_diamond_stitch_{diamond_index:02d}',\n            corners,.0032,'charcoal2',sides=8\n        )\n\n# Small crystal-look buttons sit at the intersections of the diamond cushions.\nbutton_x=[-.69,-.23,.23,.69]\nbutton_y=[.985,1.295,1.605]\nbutton_index=0\nfor by in button_y:\n    for bx in button_x:\n        button_index+=1\n        superellipsoid(\n            f'Headboard_tuft_button_base_{button_index:02d}',\n            (bx,by,-1.347),(.027,.027,.007),\n            'charcoal2',.62,24,16\n        )\n        superellipsoid(\n            f'Headboard_crystal_tuft_button_{button_index:02d}',\n            (bx,by,-1.336),(.019,.019,.011),\n            'headboard_crystal',.82,32,20\n        )\n\n# Existing RGB zone lighting is routed along the padded outer perimeter in the native renderer.\n# Original headboard mounting brackets are kept; all other bed geometry remains unchanged.\nfor side in (-1,1):\n    boxsoft(f'Headboard_mount_{side}',(side*.92,.74,-1.53),(.105,.48,.13),'underside',.40)"

def patch_bed_geometry(source: str) -> str:
    if source.count(OLD_GEOMETRY) != 1:
        raise RuntimeError(
            "Bed geometry patch did not find exactly one original pillow/headboard block; "
            "refusing to generate an unexpected model."
        )
    source = source.replace(OLD_GEOMETRY, NEW_GEOMETRY, 1)

    # Trimesh's glTF exporter only writes NORMAL accessors when vertex_normals
    # have already been evaluated and cached. Without this, the diamond pads
    # become faceted flat-shaded triangles in the runtime and editable GLBs.
    smooth_mesh_marker = "        m.fix_normals()\\n"
    if source.count(smooth_mesh_marker) != 1:
        raise RuntimeError("Bed mesh smooth-normal marker changed; refusing a flat-shaded GLB.")
    source = source.replace(
        smooth_mesh_marker,
        smooth_mesh_marker + "        m.vertex_normals  # cache smooth per-vertex normals for GLB export\\n",
        1
    )
    runtime_mesh_marker = "    merged.fix_normals()\\n"
    if source.count(runtime_mesh_marker) != 1:
        raise RuntimeError("Runtime mesh normal marker changed; refusing a flat-shaded runtime GLB.")
    source = source.replace(
        runtime_mesh_marker,
        runtime_mesh_marker + "    merged.vertex_normals  # include normals in optimized runtime batches\\n",
        1
    )

    old_design = "'design':'Charcoal channel-upholstered headboard, padded upholstered rails, silver cotton bedding, graphite duvet, midnight ribbed throw',"
    new_design = "'design':'Black upholstered diamond-tufted headboard with raised padded diamond cells, crystal-look tuft buttons and controllable recessed RGB perimeter lighting; original bed frame, mattress and bedding retained',"
    if source.count(old_design) != 1:
        raise RuntimeError("Bed metadata design marker changed; update the design patch.")
    source = source.replace(old_design, new_design, 1)
    return source
